def prepare_ml_columns(df):
    result = df

    for col_name in boolean_features:
        result = result.withColumn(
            col_name,
            F.coalesce(
                F.col(col_name).cast("double"),
                F.lit(0.0)
            )
        )

    for col_name in numeric_features:
        result = result.withColumn(
            col_name,
            F.coalesce(
                F.col(col_name).cast("double"),
                F.lit(0.0)
            )
        )

    result = result.withColumn(
        label_col,
        F.col(label_col).cast("double")
    )

    return result


train_ml = prepare_ml_columns(train_df)
test_ml = prepare_ml_columns(test_df)
